package com.vikash.bedtimestories.data

/** Longer retellings, written to be read aloud in about five to seven minutes. */
internal val LONG_ORIGINALS_B: Map<String, List<LP>> = mapOf(
    "star-painter" to listOf(
        LP("ladder hero", "It was a quiet night, and the whole house was asleep. {name} looked out of the window and saw something very strange: a tall wooden ladder, leaning right against the sky."),
        LP("ladder hero oak", "{name} tiptoed outside in soft slippers. The grass was cool and wet. The ladder went up, up, up, past the oak tree, past the clouds, all the way into the dark."),
        LP("ladder hero star", "Step by step, {name} began to climb. Creak, went the ladder. Creak, creak. The air smelled cold and sweet, like a candle that has just been blown out."),
        LP("painter cloud", "At the very top sat an old woman on a cloud. She had a long brush, a bucket of silver paint, and little silver speckles all over her apron and the tip of her nose."),
        LP("painter star", "“I am the Star Painter,” she said. “Every night I paint the stars back on. But tonight my arms are tired, and half the sky is still dark.”"),
        LP("painter hero", "{name} looked at the empty sky and thought of all the children who would wake up in the night and see no stars at all. That did not seem right."),
        LP("painter star", "She rubbed her shoulders and sighed. On one side, the stars were bright and twinkling. On the other side, there was only a big, empty darkness, quiet as a closed door."),
        LP("hero painter", "“I can help,” said {name}, “but I do not know how to paint a star.” The Star Painter laughed kindly. “Nobody does, the first time. Just begin.”"),
        LP("hero painter sparkle", "She held out the brush. It was heavier than it looked, and it hummed a little, like a bee. {name} dipped it into the bucket, and the silver paint shimmered and swirled."),
        LP("hero star", "{name}’s first star was wobbly. One point leaned left, and one point leaned right. “Oh no,” said {name}. “It is all crooked.” “Keep going,” said the Star Painter."),
        LP("hero star", "The second star had too many points. One, two, three, four, five, six, seven! {name} giggled. “That one looks like a snowflake.” “Then it is a snowflake star,” said the Star Painter."),
        LP("hero star sparkle", "But the third one twinkled. And the fourth one shone. Dip, swish, sparkle. Dip, swish, sparkle. Soon the brush was dancing across the sky, and {name} was dancing with it."),
        LP("painter hero star", "Big stars and tiny stars. Stars in a line, like a necklace. Stars in a little bunch, like grapes. The dark half of the sky filled up, one bright dot at a time."),
        LP("painter hero star", "“Look,” said the Star Painter, pointing down. Far below, in windows all over the town, children in their beds were pointing up at the new stars."),
        LP("painter star", "“Which star do they like best?” asked {name}. The Star Painter smiled a crinkly smile. “They like the wobbly one best. It looks like it is waving.”"),
        LP("hero painter star", "{name} looked at that very first star. It was small and crooked, and it was the friendliest star in the whole sky. “You do not have to be perfect,” said the Star Painter. “You only have to begin.”"),
        LP("hero ladder", "{name} gave back the brush and let out a great big yawn. The Star Painter yawned too. “Thank you, little painter,” she said. “Now it is time for bed.” Slowly, step by step, {name} climbed down the ladder."),
        LP("hero~ zzz star", "Back in the warm bed, {name} snuggled under the blanket, sleepy and proud. From the pillow, {name} could see it: one wobbly little star, waving goodnight."),
        LP("star painter~ hero~", "Goodnight, wobbly star. Goodnight, Star Painter. Goodnight, {name}. The whole sky twinkled softly, and everyone was fast asleep."),
    ),
    "hedgehog-hug" to listOf(
        LP("hedgehog oak", "Deep in the green forest, under tall ferns and old oak trees, lived a little hedgehog named Hazel. She had a pointy nose, bright black eyes, and a back covered in prickles."),
        LP("hedgehog bird heart", "Hazel wanted a hug more than anything. She watched the rabbits hug. She watched the birds snuggle together in their nests. Every hug looked warm and lovely."),
        LP("hedgehog heart", "Hazel tried to hug a pinecone, but it was even pricklier than she was. She tried to hug a mushroom, and it went squish. “Oh dear,” sighed Hazel. “Hugs are hard.”"),
        LP("hedgehog squirrel", "But whenever Hazel came close, the other animals said, “Ouch!” and hopped away from her prickles. The squirrel said ouch. The mole said ouch. Even the soft moss seemed to whisper ouch."),
        LP("hedgehog hero", "One evening, {name} was walking through the forest and found Hazel sitting alone under a fern. Her little nose was pink, and a tear was rolling down it."),
        LP("hedgehog hero", "“Nobody can hug me,” sniffed the hedgehog. “I am too prickly to be a friend.” {name} sat down beside her, close but careful, on the soft green moss."),
        LP("hero hedgehog", "{name} thought for a while. A little breeze rustled the fern above them, and an owl hooted far away. Then {name} smiled a slow, kind smile."),
        LP("hero hedgehog", "“There are many ways to hug,” said {name}. “A wave can be a hug. A shared blackberry can be a hug. So can sitting close and listening.”"),
        LP("hedgehog hero heart", "Hazel blinked. “Really? A hug without arms?” “Really,” said {name}. “A hug is just a way of saying, I care about you. You can say that in lots of ways.”"),
        LP("hedgehog squirrel", "So Hazel tried. First she found the squirrel, who was busy burying acorns. Hazel waved her little paw. Wave, wave. The squirrel stopped and waved back. “Hello, Hazel!”"),
        LP("hedgehog heart", "Next she found the mole, who was hungry after a long day of digging. Hazel shared her blackberries, the plumpest and juiciest ones. “Mmm,” said the mole. “Thank you, Hazel.”"),
        LP("hedgehog frog", "Then she found the old toad sitting on a log. The toad began a very long story about a very long rain. Hazel listened all the way to the end. Not one yawn, not one fidget, not even a peek at the moon."),
        LP("frog hedgehog heart", "“Nobody ever listens to the end,” croaked the toad, smiling a wide toad smile. “That felt just like a hug.” Hazel’s nose turned pink again, but this time it was from happiness."),
        LP("hedgehog squirrel frog", "Soon everyone wanted to sit beside Hazel. The squirrel brought acorns. The toad brought another story. They sat in a circle, close and cozy, and nobody said ouch at all."),
        LP("hero hedgehog", "Then the sun went down, and the night grew cold. Hazel shivered. {name} took off a soft woolly scarf and wrapped it gently around her, round and round."),
        LP("hero hedgehog heart", "And then {name} gave her a hug. The scarf was soft, the hug was warm, and not one prickle poked through. Now Hazel could be hugged, prickles and all."),
        LP("hedgehog heart hero", "“That was my first real hug,” said Hazel. “It will not be your last,” said {name}. And Hazel smiled the biggest smile a hedgehog can smile."),
        LP("hedgehog~ squirrel~ frog~", "One by one, the forest friends said goodnight. The squirrel curled up in the oak tree. The toad settled under the log. Hazel curled into a little round ball, warm in her scarf."),
        LP("hero~ hedgehog~ zzz", "The fern leaves closed over them like a blanket. Somewhere a cricket sang softly. Goodnight, Hazel. Goodnight, forest. Goodnight, {name}."),
    ),
    "dream-train" to listOf(
        LP("train", "It was bedtime, and the room was dark and still. Then, at the edge of {name}’s bed, something began to glow: a little blue train with round yellow windows, waiting quietly."),
        LP("conductor train", "“All aboard for Dreamland,” whispered the conductor, a sleepy old cat in a tiny hat. The cat had soft grey fur and a silver whistle hanging on a string."),
        LP("train hero", "{name} climbed into the little carriage. Inside there was a soft seat and a blanket, folded just so. {name} pulled up the blanket, all the way to the chin."),
        LP("conductor train", "The cat blew the whistle, very gently. Toot... toot. The train began to move. Chug... chug... chug... It rolled slowly out of the bedroom window and over the rooftops."),
        LP("train house star", "Below, the houses were sleeping. Their chimneys puffed tiny clouds, and their windows were dark. The train chugged past the chimney pots and up into the starry sky."),
        LP("sheep sheep sheep~", "First stop: the Yawning Hills. The hills were round and green and dotted with sheep, and the sheep were already counting themselves. One sheep, two sheep, three sheep..."),
        LP("hero conductor sheep~", "Four sheep, five sheep, six sheep... yawn. {name} gave a great big yawn. So did the cat. The cat yawned so wide that the tiny hat nearly fell off."),
        LP("train cloud", "Toot... toot. The train moved on. Second stop: the Pillow Fields, where everything was soft and white. The grass was soft. The hills were soft. Even the rocks were soft, like marshmallows."),
        LP("train cloud~", "Fluffy clouds rested on the ground like big sleepy pillows. The train went slower now. Chug... chug... The wheels were getting sleepy too."),
        LP("train cloud", "Little bunnies made of cloud hopped beside the track, soft and slow. Hop... hop... hop. One of them yawned, and its fluffy ears flopped down over its eyes."),
        LP("conductor hero", "The cat brought {name} a cup of warm milk with a sprinkle of starlight on top. It tasted like honey and moonbeams. “For the journey,” purred the cat."),
        LP("hero conductor", "{name} sipped the milk slowly. It made a warm, cozy feeling, starting in the tummy and spreading all the way down to the toes. The cat purred a deep, rumbly purr."),
        LP("train star sparkle", "The train rolled on through the night. Stars drifted past the windows like slow, shining fish. A shooting star waved its sparkly tail, and {name} waved back."),
        LP("conductor hero", "Third stop: the Quiet Lake. It was smooth as glass, with the moon floating in the middle. There were no waves, no wind, and no sound at all. Only quiet."),
        LP("conductor hero", "A family of ducks floated by, fast asleep, their heads tucked under their wings. The cat put a paw to its lips. “Shh,” it whispered. {name} whispered back, “Shh.”"),
        LP("train hero", "The train rolled softly along the shore. Chug... chug... chug. {name}’s eyes were growing heavy. The seat was so soft. The blanket was so warm."),
        LP("conductor hero", "The cat tucked the blanket in around {name}’s toes. “Almost there,” whispered the cat. “Close your eyes, if you like. The train knows the way.”"),
        LP("train cloud~", "Chug... chug... The train slowed down. Chug... The wheels hummed a soft lullaby. Shhh... shhh... The little blue train rolled gently to a stop."),
        LP("conductor zzz hero~", "“Last stop, Dreamland,” purred the cat, very softly. But {name} did not hear. {name} was already there."),
        LP("train conductor~ hero~", "The cat curled up on the seat and closed both eyes too. The little blue train glowed quietly in the dark. Goodnight, little train. Goodnight, sleepy cat. Goodnight, little traveler."),
    ),
    "thank-you-tree" to listOf(
        LP("hero tree", "It was a snowy evening. Soft white flakes floated down and covered the hills, the paths and the rooftops. {name} went out in warm boots for one last look at the snow."),
        LP("fox tree hero", "At the top of the hill stood a bare winter tree, with no leaves at all. Beside it was a little fox named Fern, standing on tiptoe and hanging something on a branch."),
        LP("fox tree hero", "“What are you doing?” asked {name}. Fern turned around, her red tail swishing in the snow. “This is the Thank-You Tree,” she said."),
        LP("fox tree bird", "“Each night I hang up one thing I am glad about. Tonight it is a feather, because the robin sang for me this morning.” The little brown feather twirled in the breeze."),
        LP("hero fox", "Fern looked at {name}. “What are you glad about today?” {name} thought and thought. It had been an ordinary sort of day. Was there anything to be glad about?"),
        LP("hero fox", "{name} remembered the morning, and lunch, and the walk in the snow. Little pictures of the day floated by, one after another, like snowflakes."),
        LP("hero tree", "Then {name} remembered. “I am glad for warm soup,” said {name}, and tied a red ribbon to a branch. The tree seemed a little less bare."),
        LP("hero tree star", "“And for my cozy bed,” said {name}, and hung up a pinecone. “And for someone who says goodnight.” That one became a little paper star."),
        LP("tree star sparkle", "One thank-you led to another. Glad for mittens. Glad for a funny story. Glad for the snow. Each thank-you became a ribbon, a pinecone, or a paper star. The branches began to sparkle."),
        LP("fox hero", "Fern clapped her paws. “You are very good at this!” “It is easy once you start looking,” said {name}. “Good things are everywhere. Most of them are just small.”"),
        LP("deer tree", "Then the snow crunched softly. Crunch, crunch. Out of the woods came a deer with big, gentle eyes. “May I add one too?” she asked. “I am glad for the moonlight.”"),
        LP("mouse tree", "Then a tiny mouse scurried up, with snow on her whiskers. “I am glad for a crumb,” squeaked the mouse. “It was a very good crumb.” Everyone laughed, and the mouse tied a tiny piece of string to the lowest branch, right where she could reach."),
        LP("bird tree star", "The robin came too, and an owl, and a family of rabbits. Glad for a warm nest. Glad for a friend. Glad for the stars. One by one, they hung up their thank-yous."),
        LP("deer tree mouse", "Soon the whole tree was glowing. Ribbons and pinecones and paper stars hung from every branch, shining in the moonlight. It was the most beautiful tree in all the snowy hills."),
        LP("fox tree hero", "“The tree was never empty,” said Fern softly. “We only had to notice.” {name} nodded. Even on an ordinary day, there were so many things to be thankful for."),
        LP("fox hero heart", "Fern gave a big fox yawn. “Goodnight, {name},” she said. “Come back tomorrow, and we will find more.” “I will,” said {name}."),
        LP("hero house", "{name} walked home through the soft snow. Crunch, crunch, crunch. One: warm soup. Two: a cozy bed. Three: a new friend named Fern. Four: a tree full of stars."),
        LP("hero~ zzz", "Tucked up in bed, {name} kept on counting. Five: the moonlight. Six: this warm blanket. Seven... eight... {name} was counting good things all the way to sleep."),
        LP("fox~ tree star", "On the snowy hill, the Thank-You Tree glowed softly, and Fern curled up beneath it, warm and fast asleep. Goodnight, Thank-You Tree."),
    ),
    "whisper-dragon" to listOf(
        LP("dragon bird", "High on a green hill, above a little village, lived Ember. Ember was a small green dragon with shiny scales, a curly tail, and a very, very big roar."),
        LP("dragon bird house", "When Ember said hello, it came out as “HELLO!” Birds fell out of trees. Leaves blew off branches. The village windows rattled in their frames."),
        LP("dragon house", "Ember did not mean to be loud. Ember only wanted to say hello. But the villagers covered their ears, and the animals ran away whenever Ember came near."),
        LP("dragon sun", "So nobody came to play. Every evening, Ember sat alone on the hill at sunset, puffing sad little smoke rings into the orange sky. Puff. Puff. Puff."),
        LP("dragon bird", "The smoke rings floated away like grey doughnuts. A little bird watched from far off in a tree. It wanted to come closer, but it was afraid of the roar."),
        LP("dragon hero", "One evening, {name} came walking up the hill with both hands over both ears. “Hello,” said {name}, just a little loudly, in case. “HELLO!” said Ember, and all the grass lay flat."),
        LP("hero dragon", "“Oh dear,” said Ember, as a big tear rolled down a green cheek. “I always do that. I only want a friend, but my voice scares everybody away.”"),
        LP("hero dragon", "{name} sat down beside the dragon. “You do not have to be loud to be heard,” said {name}. “Try a whisper. A whisper makes people lean in close.”"),
        LP("dragon hero", "“A whisper?” said Ember. “I have never tried a whisper.” Ember took a deep breath. In, in, in. The dragon’s tummy grew round like a balloon."),
        LP("dragon hero", "The first whisper blew {name}’s hat right off. Whoosh! It sailed away over the hill. {name} laughed. “A little softer,” said {name}. “You can do it.”"),
        LP("dragon hero", "The second whisper only ruffled the grass. Shhhh. A daisy nodded its head. “Better,” said {name}. “Even softer this time.”"),
        LP("dragon hero", "Ember wiggled and fidgeted. Being quiet was very hard for a dragon. “Think of something small,” said {name}. “Like a sleeping kitten, or a falling leaf.”"),
        LP("dragon hero heart", "Ember closed both eyes and tried once more. The third whisper was as soft as a candle flame: “Hello.” It was a lovely sound, warm and gentle. {name} clapped."),
        LP("rabbit dragon", "Something rustled in the grass. A rabbit crept closer, one hop at a time. “Did you say hello?” asked the rabbit. “Hello,” whispered Ember. The rabbit sat right down beside the dragon’s tail."),
        LP("sheep bird dragon", "Then a lamb came, and a little bird. Then the children from the village came running up the hill. “What is that soft sound?” they asked. “Shh,” said the rabbit. “Listen.”"),
        LP("rabbit sheep dragon", "Ember whispered a story about the clouds: how they float, how they nap, how they turn pink at sunset. Everyone leaned in close to listen. Nobody covered their ears at all."),
        LP("dragon hero star", "When the story ended, the sky was dark and full of stars. The children went home to bed. Ember looked at {name}. “Thank you,” whispered the dragon. “May I fly you home?”"),
        LP("dragon hero house", "{name} climbed onto Ember’s back. The dragon flew low and quiet over the sleeping roofs, wings swishing softly. Swish... swish... Not one window rattled."),
        LP("dragon hero house", "Ember set {name} down by the front door, as gently as a feather. “Goodnight,” whispered the dragon. And it was the softest sound in the world."),
        LP("dragon~ hero~ zzz", "Back on the hill, Ember curled up in the grass and closed both eyes. In a warm bed, {name} did the same. The whole village slept, quiet and peaceful, all night long."),
    ),
    "blanket-boat" to listOf(
        LP("hero house", "It was bedtime. {name} was tucked in, warm and snug, with the blanket pulled up high. Then the lamp clicked off, and the room went soft and dark."),
        LP("boat hero", "Something wonderful began to happen. {name}’s blanket began to ripple like water. The bed rocked gently, side to side. Swish... swish..."),
        LP("boat star", "The walls melted away into the night sky. The floor became a wide, calm sea. The bed had become a little boat, bobbing on the water under a sky full of stars."),
        LP("hero boat", "{name} sat up and looked around. The water was dark blue and silver. It smelled fresh and salty. Tiny waves lapped against the boat. Lap, lap, lap."),
        LP("hero boat", "It was not scary at all. The sea was calm and friendly, and the boat felt as safe and soft as a bed. {name} snuggled down, cozy and curious, to see where it would go."),
        LP("whale boat", "Then the sea gave a great, slow swell. A whale as big as a house swam up beside the boat. Its skin was smooth and grey, and its eyes were kind."),
        LP("whale hero", "“Where are you sailing tonight?” asked the whale in a deep, slow voice. “To wherever dreams begin,” said {name}. “But I do not know the way.”"),
        LP("whale sparkle boat", "“Then follow the moon path,” said the whale, and blew a fountain of sparkling mist to show the way. The mist fell like glitter on the water."),
        LP("boat hero", "There it was: a long silver stripe across the sea, made of moonlight. The boat drifted onto it all by itself. The whale swam alongside, slow and steady."),
        LP("seal seal~", "They passed an island of sleeping seals. The seals lay in a heap, round and shiny, snoring softly. Snore... snore... One seal opened one eye, smiled, and went back to sleep."),
        LP("sparkle boat hero", "They passed little glowing fish that drifted under the boat like tiny lanterns. Blue ones, green ones, gold ones. {name} trailed a hand in the cool water, and the fish tickled it."),
        LP("sparkle hero", "{name} giggled. The fish made little circles of light that spread out across the water, ring after ring, until they faded away into the dark."),
        LP("boat hero star", "They passed a lighthouse on a rock. Its light blinked slowly, like a tired eye. Blink... blink... blink. “Goodnight, lighthouse,” whispered {name}."),
        LP("whale boat", "The whale began to hum. It was a deep, low song, as if the sea itself were singing. Hmmm... hmmm... The song went right through the boat and made it feel warm."),
        LP("whale boat hero", "“Is that a lullaby?” asked {name}. “It is the oldest lullaby in the sea,” said the whale. “My mother sang it to me, and her mother sang it to her.”"),
        LP("boat hero", "The waves rocked the boat. Up... and down. Up... and down. {name} lay back on the pillow and watched the stars sway overhead."),
        LP("star boat hero", "One star. Two stars. Three stars, swaying gently above like a mobile over a cradle. The sky was so big, and the little boat was so cozy."),
        LP("whale hero", "{name}’s eyes grew heavy. “Are we nearly there?” “Nearly,” said the whale softly. “Just keep floating. Dreams are very close now.”"),
        LP("whale zzz hero~", "“Here is where dreams begin,” the whale said quietly. The sea became a blanket again, warm and still. The boat became a bed. And {name} sailed on, fast asleep."),
        LP("whale~ seal~ zzz", "Far away, the whale sank slowly into the deep, still humming. The seals snored on their island. The lighthouse blinked. Goodnight, sea. Goodnight, whale. Goodnight, {name}."),
    ),
)
